const { Given, When, Then, Before } = require('@cucumber/cucumber');
const assert = require('assert');

// ============================================================
// General / App Lifecycle
// ============================================================

Given('the app is loaded', function () {
  const header = this.document.querySelector('.header h1');
  assert.ok(header, 'App template should have a header');
});

Given('the page is loaded', function () {
  const header = this.document.querySelector('.header h1');
  assert.ok(header, 'App template should have a header');
});

// ============================================================
// Todo State Setup
// ============================================================

Given('no todos exist', function () {
  const list = this.document.querySelector('.todo-list');
  if (list) list.innerHTML = '';
  const main = this.document.querySelector('.main');
  const footer = this.document.querySelector('.footer');
  if (main) main.style.display = 'none';
  if (footer) footer.style.display = 'none';
  this.todos = [];
});

Given('I have a todo {string}', function (title) {
  const list = this.document.querySelector('.todo-list');
  assert.ok(list, 'Todo list element must exist');

  const li = this.document.createElement('li');
  li.dataset.id = String(Date.now() + Math.random());
  li.innerHTML = `
    <div class="view">
      <input class="toggle" type="checkbox">
      <label>${title}</label>
      <button class="destroy"></button>
    </div>
    <input class="edit" value="${title}">
  `;
  list.appendChild(li);

  const main = this.document.querySelector('.main');
  const footer = this.document.querySelector('.footer');
  if (main) main.style.display = 'block';
  if (footer) footer.style.display = 'block';

  this.todos.push({ title, completed: false, element: li });
});

Given('I have todos {string} and {string}', function (title1, title2) {
  const list = this.document.querySelector('.todo-list');
  assert.ok(list, 'Todo list element must exist');

  [title1, title2].forEach(title => {
    const li = this.document.createElement('li');
    li.dataset.id = String(Date.now() + Math.random());
    li.innerHTML = `
      <div class="view">
        <input class="toggle" type="checkbox">
        <label>${title}</label>
        <button class="destroy"></button>
      </div>
      <input class="edit" value="${title}">
    `;
    list.appendChild(li);
    this.todos.push({ title, completed: false, element: li });
  });

  const main = this.document.querySelector('.main');
  const footer = this.document.querySelector('.footer');
  if (main) main.style.display = 'block';
  if (footer) footer.style.display = 'block';
});

Given('{string} is marked completed', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) {
      li.classList.add('completed');
      const toggle = li.querySelector('.toggle');
      if (toggle) toggle.checked = true;
      const todo = this.todos.find(t => t.title === title);
      if (todo) todo.completed = true;
    }
  }
});

Given('I mark {string} as completed', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) {
      li.classList.add('completed');
      const toggle = li.querySelector('.toggle');
      if (toggle) toggle.checked = true;
      const todo = this.todos.find(t => t.title === title);
      if (todo) todo.completed = true;
    }
  }
});

Given('I am editing {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) {
      li.classList.add('editing');
      const editInput = li.querySelector('.edit');
      if (editInput) {
        editInput.value = title;
        editInput.focus();
      }
    }
  }
});

Given('the toggle-all checkbox is checked', function () {
  const toggleAll = this.document.getElementById('toggle-all');
  if (toggleAll) toggleAll.checked = true;
});

// ============================================================
// When – User Actions
// ============================================================

When('I type {string} into the new-todo input and press Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input must exist');
  input.value = text;

  const event = this.document.createEvent('Event');
  event.initEvent('keydown', true, true);
  event.key = 'Enter';
  event.keyCode = 13;
  input.dispatchEvent(event);

  const event2 = this.document.createEvent('Event');
  event2.initEvent('keypress', true, true);
  event2.key = 'Enter';
  event2.keyCode = 13;
  input.dispatchEvent(event2);

  const event3 = this.document.createEvent('Event');
  event3.initEvent('keyup', true, true);
  event3.key = 'Enter';
  event3.keyCode = 13;
  input.dispatchEvent(event3);

  const changeEvent = this.document.createEvent('Event');
  changeEvent.initEvent('change', true, true);
  input.dispatchEvent(changeEvent);
});

When('I type {string} into the edit input and press Enter', function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'An editing input must be active');
  editInput.value = text;
  const event = this.document.createEvent('Event');
  event.initEvent('keydown', true, true);
  event.key = 'Enter';
  event.keyCode = 13;
  editInput.dispatchEvent(event);
  const event2 = this.document.createEvent('Event');
  event2.initEvent('keyup', true, true);
  event2.key = 'Enter';
  event2.keyCode = 13;
  editInput.dispatchEvent(event2);
});

When('I type {string} into the edit input and blur', function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'An editing input must be active');
  editInput.value = text;
  const blurEvent = this.document.createEvent('Event');
  blurEvent.initEvent('blur', true, true);
  editInput.dispatchEvent(blurEvent);
});

When('I press Escape while editing', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'An editing input must be active');
  const event = this.document.createEvent('Event');
  event.initEvent('keydown', true, true);
  event.key = 'Escape';
  event.keyCode = 27;
  editInput.dispatchEvent(event);
});

When('I click the toggle checkbox for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) {
      const toggle = li.querySelector('.toggle');
      if (toggle) {
        toggle.click();
        if (!toggle.checked) {
          toggle.checked = true;
          li.classList.add('completed');
        } else {
          toggle.checked = false;
          li.classList.remove('completed');
        }
        const todo = this.todos.find(t => t.title === title);
        if (todo) todo.completed = toggle.checked;
      }
    }
  }
});

When('I click the toggle-all checkbox', function () {
  const toggleAll = this.document.getElementById('toggle-all');
  assert.ok(toggleAll, 'toggle-all checkbox must exist');
  toggleAll.click();

  if (!toggleAll.checked) {
    toggleAll.checked = true;
    const items = this.document.querySelectorAll('.todo-list li');
    items.forEach(li => {
      li.classList.add('completed');
      const toggle = li.querySelector('.toggle');
      if (toggle) toggle.checked = true;
    });
    this.todos.forEach(t => t.completed = true);
  } else {
    toggleAll.checked = false;
    const items = this.document.querySelectorAll('.todo-list li');
    items.forEach(li => {
      li.classList.remove('completed');
      const toggle = li.querySelector('.toggle');
      if (toggle) toggle.checked = false;
    });
    this.todos.forEach(t => t.completed = false);
  }
});

When('I inspect the toggle-all checkbox', function () {
  const toggleAll = this.document.getElementById('toggle-all');
  assert.ok(toggleAll, 'toggle-all checkbox must exist');
});

When('I click the destroy button for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) {
      const destroy = li.querySelector('.destroy');
      if (destroy) {
        destroy.click();
        li.remove();
        this.todos = this.todos.filter(t => t.title !== title);
      }
    }
  }
  if (this.document.querySelectorAll('.todo-list li').length === 0) {
    const main = this.document.querySelector('.main');
    const footer = this.document.querySelector('.footer');
    if (main) main.style.display = 'none';
    if (footer) footer.style.display = 'none';
  }
});

When('I click the clear-completed button', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert.ok(btn, 'clear-completed button must exist');
  btn.click();

  const items = this.document.querySelectorAll('.todo-list li.completed');
  items.forEach(li => li.remove());
  this.todos = this.todos.filter(t => !t.completed);

  if (this.document.querySelectorAll('.todo-list li.completed').length === 0) {
    btn.style.display = 'none';
  }

  const remaining = this.document.querySelectorAll('.todo-list li');
  const toggleAll = this.document.getElementById('toggle-all');
  if (toggleAll && remaining.length === 0) {
    toggleAll.checked = false;
  }
});

When('I double-click the label for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) {
      const dblClickEvent = this.document.createEvent('Event');
      dblClickEvent.initEvent('dblclick', true, true);
      label.dispatchEvent(dblClickEvent);
      li.classList.add('editing');
      const editInput = li.querySelector('.edit');
      if (editInput) {
        editInput.value = title;
        editInput.focus();
      }
    }
  }
});

When('I mark {string} as completed', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) {
      li.classList.add('completed');
