  this.window.location.hash = hash;
  const hashEvent = this.document.createEvent('Event');
  hashEvent.initEvent('hashchange', true, true);
  this.window.dispatchEvent(hashEvent);
});

When('I reload the page', function () {
  const { Window } = require('happy-dom');
  const fs = require('fs');
  const path = require('path');

  const prevHash = this.window.location.hash;

  let html = fs.readFileSync(path.resolve(__dirname, '../../index.html'), 'utf8');
  const win = new Window({ url: 'http://localhost:3000/' + prevHash });
  const doc = win.document;
  doc.write(html);
