Then('localStorage contains a key matching {string}', function (pattern) {
  // Find keys matching the pattern
  const keys = Object.keys(this.localStorage._storage || {});
  // In happy-dom v20, localStorage might need different access
  let found = false;
  try {
    for (let i = 0; i < this.localStorage.length; i++) {
      const key = this.localStorage.key(i);
      if (key && key.match(pattern.replace(/\*/g, '.*'))) {
        found = true;
        break;
      }
    }
  } catch (e) {
    // Fallback
    const store = this.localStorage;
    for (const k in store) {
      if (typeof store[k] === 'string' && k.match(pattern.replace(/\*/g, '.*'))) {
        found = true;
        break;
      }
    }
  }
  assert.ok(found, 'Expected localStorage to contain a key matching "' + pattern + '"');
});

Then('the stored value is valid JSON with objects having keys {string}, {string}, {string}', function (key1, key2, key3) {
  // Find the storage key
  let storedValue = null;
  try {
    for (let i = 0; i < this.localStorage.length; i++) {
      const key = this.localStorage.key(i);
      if (key && key.startsWith('todos-')) {
        storedValue = this.localStorage.getItem(key);
        break;
      }
    }
  } catch (e) {
    // Fallback
    const store = this.localStorage;
    for (const k in store) {
      if (typeof store[k] === 'string' && k.startsWith('todos-')) {
        storedValue = store[k];
        break;
      }
    }
  }
  assert.ok(storedValue, 'Expected a stored value in localStorage');
  let parsed;
  try {
    parsed = JSON.parse(storedValue);
  } catch (e) {
    assert.fail('Expected stored value to be valid JSON, but got: ' + storedValue);
  }
  assert.ok(Array.isArray(parsed), 'Expected stored value to be an array');
  for (const item of parsed) {
    assert.ok(item.hasOwnProperty(key1), 'Expected item to have key "' + key1 + '"');
    assert.ok(item.hasOwnProperty(key2), 'Expected item to have key "' + key2 + '"');
    assert.ok(item.hasOwnProperty(key3), 'Expected item to have key "' + key3 + '"');
  }
});

Then('the localStorage key is empty or absent', function () {
  let found = false;
  try {
    for (let i = 0; i < this.localStorage.length; i++) {
      const key = this.localStorage.key(i);
      if (key && key.startsWith('todos-')) {
        const val = this.localStorage.getItem(key);
        if (val) {
          const parsed = JSON.parse(val);
          found = Array.isArray(parsed) && parsed.length > 0;
        }
        break;
      }
    }
  } catch (e) {
    // Fallback
    const store = this.localStorage;
    for (const k in store) {
      if (typeof store[k] === 'string' && k.startsWith('todos-')) {
        if (store[k]) {
          try {
            const parsed = JSON.parse(store[k]);
            found = Array.isArray(parsed) && parsed.length > 0;
          } catch (e) {}
        }
        break;
      }
    }
  }
  assert.ok(!found, 'Expected localStorage key to be empty or absent');
});

