const { setWorldConstructor, Before } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

function TodoWorld({ parameters }) {
  this.window = null;
  this.document = null;
  this.localStorage = null;
  this.todos = [];
}

Before(function () {
  // Use the test-specific HTML template with relative paths resolved
  let html = fs.readFileSync(path.resolve(__dirname, '../../index.html'), 'utf8');

  const win = new Window({ url: 'http://localhost:3000/' });
  const doc = win.document;

  doc.write(html);
  doc.close();

  // Replace script src to load from the actual app file
  // Inject the app script into the DOM
  const appScript = doc.querySelector('script[src="js/app.js"]');
  if (appScript) {
    // Load the app.js into the window context
    const appCode = fs.readFileSync(path.resolve(__dirname, '../../js/app.js'), 'utf8');
    try {
      // Use a sandboxed eval approach
      const fn = new win.Function('window', 'document', 'localStorage', appCode);
      fn(win, doc, win.localStorage);
    } catch (e) {
      // App code may not exist yet; that's fine, it's production work
    }
  }

  this.window = win;
  this.document = doc;
  this.localStorage = win.localStorage;
});

setWorldConstructor(TodoWorld);

