(function (window, document, localStorage) {
  'use strict';

  var ENTER_KEY = 13;

  // DOM references
  var todoList = document.querySelector('.todo-list');
  var newTodo = document.querySelector('.new-todo');
  var main = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var toggleAll = document.getElementById('toggle-all');

  // Remove sample items from template
  todoList.innerHTML = '';

  function createTodoItem(title) {
    var li = document.createElement('li');
    li.innerHTML =
      '<div class="view">' +
        '<input class="toggle" type="checkbox">' +
        '<label>' + title + '</label>' +
        '<button class="destroy"></button>' +
      '</div>' +
      '<input class="edit" value="' + title + '">';
    return li;
  }

  /** @planks("I type {string} into the new-todo input and press Enter") */
  function addTodo(title) {
    var trimmed = title.trim();
    if (trimmed === '') return;

    var li = createTodoItem(trimmed);
    todoList.appendChild(li);

    newTodo.value = '';
    main.style.display = 'block';
    footer.style.display = 'block';
    updateToggleAll();
  }

  function updateToggleAll() {
    var items = todoList.querySelectorAll('li');
    var completed = todoList.querySelectorAll('li.completed');
    toggleAll.checked = items.length > 0 && completed.length === items.length;
  }

  // Delegate click events on the todo-list
  todoList.addEventListener('click', function (e) {
    var target = e.target;

    // Toggle checkbox
    if (target.classList.contains('toggle')) {
      var li = target.closest('li');
      if (target.checked) {
        li.classList.add('completed');
      } else {
        li.classList.remove('completed');
      }
      updateToggleAll();
    }

    // Destroy button
    if (target.classList.contains('destroy')) {
      var li = target.closest('li');
      li.parentNode.removeChild(li);
      if (todoList.querySelectorAll('li').length === 0) {
        main.style.display = 'none';
        footer.style.display = 'none';
      }
      updateToggleAll();
    }
  });

  // Toggle-all checkbox
  toggleAll.addEventListener('click', function () {
    var items = todoList.querySelectorAll('li');
    items.forEach(function (li) {
      if (toggleAll.checked) {
        li.classList.add('completed');
        li.querySelector('.toggle').checked = true;
      } else {
        li.classList.remove('completed');
        li.querySelector('.toggle').checked = false;
      }
    });
  });

  newTodo.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodo.value);
    }
  });

})(window, document, localStorage);

