(function (window, document, localStorage) {
  'use strict';

  var ENTER_KEY = 13;

  // DOM references
  var todoList = document.querySelector('.todo-list');
  var newTodo = document.querySelector('.new-todo');
  var main = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var toggleAll = document.getElementById('toggle-all');
  var todoCount = document.querySelector('.todo-count');
  var clearCompleted = document.querySelector('.clear-completed');

  // Remove sample items from template
  todoList.innerHTML = '';

  function createTodoItem(title) {
    var li = document.createElement('li');
    li.innerHTML =
      '<div class="view">' +
        '<input class="toggle" type="checkbox">' +
        '<label>' + title + '</label>' +
        '<button class="destroy"></button>' +
      '</div>' +
      '<input class="edit" value="' + title + '">';
    return li;
  }

  /** @planks("I type {string} into the new-todo input and press Enter") */
  function addTodo(title) {
    var trimmed = title.trim();
    if (trimmed === '') return;

    var li = createTodoItem(trimmed);
    todoList.appendChild(li);

    newTodo.value = '';
    main.style.display = 'block';
    footer.style.display = 'block';
    updateCounters();
  }

  function getActiveCount() {
    var all = todoList.querySelectorAll('li');
    var completed = todoList.querySelectorAll('li.completed');
    return all.length - completed.length;
  }

  function getCompletedCount() {
    return todoList.querySelectorAll('li.completed').length;
  }

  function updateCounters() {
    var active = getActiveCount();
    var completed = getCompletedCount();
    var total = todoList.querySelectorAll('li').length;

    // Update todo-count
    if (todoCount) {
      var word = active === 1 ? 'item' : 'items';
      todoCount.innerHTML = '<strong>' + active + '</strong> ' + word + ' left';
    }

    // Update toggle-all
    toggleAll.checked = total > 0 && completed === total;

    // Show/hide clear-completed
    if (clearCompleted) {
      if (completed > 0) {
        clearCompleted.style.display = 'block';
      } else {
        clearCompleted.style.display = 'none';
      }
    }

    // Show/hide main and footer
    if (total === 0) {
      main.style.display = 'none';
      footer.style.display = 'none';
    } else {
      main.style.display = 'block';
      footer.style.display = 'block';
    }
  }

  // Delegate click events on the todo-list
  /** @planks("I click the toggle checkbox for {string}") @planks("I click the destroy button for {string}") */
  todoList.addEventListener('click', function (e) {
    var target = e.target;

    // Toggle checkbox
