(function (window, document, localStorage) {
  'use strict';

  var ENTER_KEY = 13;
  var ESC_KEY = 27;
  var STORAGE_KEY = 'todos-todomvc';

  // DOM references
  var todoList = document.querySelector('.todo-list');
  var newTodo = document.querySelector('.new-todo');
  var main = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var toggleAll = document.getElementById('toggle-all');
  var todoCount = document.querySelector('.todo-count');
  var clearCompleted = document.querySelector('.clear-completed');
  var filters = document.querySelector('.filters');

  var currentRoute = 'all';

  // Load state from localStorage
  function loadState() {
    try {
      var stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        var items = JSON.parse(stored);
        var listFrag = document.createDocumentFragment();
        items.forEach(function (item) {
          var li = createTodoItem(item.title);
          if (item.completed) {
            li.classList.add('completed');
            li.querySelector('.toggle').checked = true;
          }
          listFrag.appendChild(li);
        });
        todoList.innerHTML = '';
        todoList.appendChild(listFrag);
        return items.length > 0;
      }
    } catch (e) {}
    return false;
  }

  // Save state to localStorage
  function saveState() {
    var items = [];
    todoList.querySelectorAll('li').forEach(function (li) {
      var label = li.querySelector('label');
      var toggle = li.querySelector('.toggle');
      items.push({
        id: li.dataset.id || String(Date.now() + Math.random()),
        title: label ? label.textContent : '',
        completed: li.classList.contains('completed')
      });
      if (!li.dataset.id) {
        li.dataset.id = items[items.length - 1].id;
      }
    });
    localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
  }

  function createTodoItem(title) {
    var li = document.createElement('li');
    li.dataset.id = String(Date.now() + Math.random());
    li.innerHTML =
      '<div class="view">' +
        '<input class="toggle" type="checkbox">' +
        '<label>' + title + '</label>' +
        '<button class="destroy"></button>' +
      '</div>' +
      '<input class="edit" value="' + title + '">';
    return li;
  }

  /** @planks("I type {string} into the new-todo input and press Enter") */
  function addTodo(title) {
    var trimmed = title.trim();
    if (trimmed === '') return;

    var li = createTodoItem(trimmed);
    todoList.appendChild(li);

    newTodo.value = '';
    updateCounters();
    saveState();
    filterTodos();
  }

  function getActiveCount() {
    var all = todoList.querySelectorAll('li');
    var completed = todoList.querySelectorAll('li.completed');
    return all.length - completed.length;
  }

  function getCompletedCount() {
    return todoList.querySelectorAll('li.completed').length;
  }

  function updateCounters() {
    var active = getActiveCount();
    var completed = getCompletedCount();
    var total = todoList.querySelectorAll('li').length;

    if (todoCount) {
      var word = active === 1 ? 'item' : 'items';
      todoCount.innerHTML = '<strong>' + active + '</strong> ' + word + ' left';
    }

    toggleAll.checked = total > 0 && completed === total;

    if (clearCompleted) {
      clearCompleted.style.display = completed > 0 ? 'block' : 'none';
    }

    if (total === 0) {
      main.style.display = 'none';
      footer.style.display = 'none';
    } else {
      main.style.display = 'block';
      footer.style.display = 'block';
    }
  }

  function filterTodos() {
    var route = currentRoute;
    todoList.querySelectorAll('li').forEach(function (li) {
      var completed = li.classList.contains('completed');
      switch (route) {
        case 'active':
          li.style.display = completed ? 'none' : '';
          break;
        case 'completed':
          li.style.display = completed ? '' : 'none';
          break;
        default:
          li.style.display = '';
      }
    });
    // Update filter link selected class
    filters.querySelectorAll('a').forEach(function (a) {
      var href = a.getAttribute('href');
      var filterName = href === '#/' ? 'all' : href.replace('#/', '');
      if (filterName === route) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    });
  }

  function setRoute(route) {
    currentRoute = route;
    filterTodos();
    localStorage.setItem(STORAGE_KEY + '-route', route);
  }

  function commitEdit(li, editInput) {
    var trimmed = editInput.value.trim();
    if (trimmed === '') {
      li.parentNode.removeChild(li);
    } else {
      li.querySelector('label').textContent = trimmed;
      li.classList.remove('editing');
    }
    updateCounters();
    saveState();
    filterTodos();
  }

  function cancelEdit(li, editInput) {
    li.classList.remove('editing');
  }

  // Handle hash changes
  /** @planks("I navigate to {string}") */
  window.addEventListener('hashchange', function () {
    var hash = window.location.hash;
    if (hash === '#/active') {
      setRoute('active');
    } else if (hash === '#/completed') {
      setRoute('completed');
    } else {
      setRoute('all');
    }
  });

  // Delegate click on filter links
  filters.addEventListener('click', function (e) {
    if (e.target.tagName === 'A') {
      // The default navigation will trigger hashchange
    }
  });

  /** @planks("I double-click the label for {string}") */
  todoList.addEventListener('dblclick', function (e) {
    var target = e.target;
    if (target.tagName === 'LABEL') {
      var li = target.closest('li');
      li.classList.add('editing');
      var editInput = li.querySelector('.edit');
      editInput.value = target.textContent;
      editInput.focus();
    }
  });

  /** @planks("I click the toggle checkbox for {string}") @planks("I click the destroy button for {string}") */
  todoList.addEventListener('click', function (e) {
    var target = e.target;

    if (target.classList.contains('toggle')) {
      var li = target.closest('li');
      if (target.checked) {
        li.classList.add('completed');
      } else {
        li.classList.remove('completed');
      }
      updateCounters();
      saveState();
      filterTodos();
    }

    if (target.classList.contains('destroy')) {
      var li = target.closest('li');
      li.parentNode.removeChild(li);
      updateCounters();
      saveState();
      filterTodos();
    }
  });

  /** @planks("I type {string} into the edit input and press Enter") @planks("I press Escape while editing") */
  todoList.addEventListener('keydown', function (e) {
    var target = e.target;
    if (target.classList.contains('edit')) {
      var li = target.closest('li');
      if (e.keyCode === ENTER_KEY) {
        commitEdit(li, target);
      } else if (e.keyCode === ESC_KEY) {
        cancelEdit(li, target);
      }
    }
  });

  /** @planks("I type {string} into the edit input and blur") */
  todoList.addEventListener('blur', function (e) {
    var target = e.target;
    if (target.classList.contains('edit')) {
      var li = target.closest('li');
      if (li.classList.contains('editing')) {
        commitEdit(li, target);
      }
    }
  }, true);

  /** @planks("I click the toggle-all checkbox") @planks("I inspect the toggle-all checkbox") */
  toggleAll.addEventListener('click', function () {
    var items = todoList.querySelectorAll('li');
    items.forEach(function (li) {
      if (toggleAll.checked) {
        li.classList.add('completed');
        li.querySelector('.toggle').checked = true;
      } else {
        li.classList.remove('completed');
        li.querySelector('.toggle').checked = false;
      }
    });
    updateCounters();
    saveState();
    filterTodos();
  });

  /** @planks("I click the clear-completed button") */
  clearCompleted.addEventListener('click', function () {
    var items = todoList.querySelectorAll('li.completed');
    items.forEach(function (li) {
      li.parentNode.removeChild(li);
    });
    updateCounters();
    saveState();
    filterTodos();
  });

  newTodo.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodo.value);
    }
  });

  // Hide clear-completed initially
  clearCompleted.style.display = 'none';

  // Restore route from localStorage
  var savedRoute = localStorage.getItem(STORAGE_KEY + '-route');
  if (savedRoute) {
    currentRoute = savedRoute;
    // Set the hash without triggering hashchange
    if (savedRoute === 'active') {
      window.location.hash = '#/active';
    } else if (savedRoute === 'completed') {
      window.location.hash = '#/completed';
    }
  }

  // Load saved state
  var hasSaved = loadState();
  if (hasSaved) {
    main.style.display = 'block';
    footer.style.display = 'block';
  }
  updateCounters();
  filterTodos();

})(window, document, localStorage);

